"""The Spec reference page (docs/reference.md, docs/gc/reference.md) and the term index are generated by tools/make_reference.py:
every function the checker has a signature for is described, the keyword lists match the parser's, and the files are current."""
import os, re, sys
ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
sys.path.insert(0, ROOT); sys.path.insert(0, os.path.join(ROOT, "tools"))
import make_reference as mr
from moxie import sigs
from moxie.pbase import HARD
bad = 0
def check(ok, msg):
    global bad
    print(("ok    " if ok else "FAIL  ") + msg)
    bad += 0 if ok else 1
described = {n for _, _, items in mr.FUNCS for n, _ in items}
names = set(re.findall(r"^fn (\w+)", sigs.SRC, re.M))
check(not (names - described), "every function with a checker signature is described" + ("" if not (names - described) else ": " + " ".join(sorted(names - described))))
check({n for n, _, _ in mr.HARD} == set(HARD), "hard keywords match the parser" + ("" if {n for n, _, _ in mr.HARD} == set(HARD) else ": %s" % sorted({n for n, _, _ in mr.HARD} ^ set(HARD))))
spec = open(os.path.join(ROOT, "docs", "spec.md")).read()
soft = re.search(r"\*\*Soft keywords \((\d+)\)\*\*", spec)
check(soft and int(soft.group(1)) == len(mr.SOFT), "soft keyword count matches the Spec (%d)" % len(mr.SOFT))
hard = re.search(r"\*\*Hard keywords \((\d+)\)\*\*", spec)
check(hard and int(hard.group(1)) == len(mr.HARD), "hard keyword count matches the Spec (%d)" % len(mr.HARD))
for gc in (False, True):
    p = os.path.join(ROOT, "docs", "gc" if gc else "", "reference.md")
    check(open(p).read() == mr.build(gc)[0], "%s is current (run tools/make_reference.py)" % os.path.relpath(p, ROOT))
sections = set(re.findall(r"\{#(s\w+)\}", spec))
used = {sec for _, _, sec in mr.HARD + mr.SOFT} | {sec for _, sec, _ in mr.FUNCS}
check(used <= sections, "every Spec section the reference points to exists" + ("" if used <= sections else ": %s" % sorted(used - sections)))
print("all passed" if not bad else "%d failed" % bad)
sys.exit(1 if bad else 0)
